fn format_display_name(
    &self,
    path: &Path,
    cwd: &Path,
    prefix: Option<&Path>,
    absolute_path: bool,
) -> Result<String, ShellError> {
    let span = self.listing_span;
    let name = if self.short_names {
        path.file_name().map(|os| os.to_string_lossy().to_string())
    } else if self.full_paths || absolute_path {
        Some(path.to_string_lossy().to_string())
    } else if let Some(prefix) = prefix {
        if let Ok(remainder) = path.strip_prefix(prefix) {
            if self.directory_only {
                let path_diff = if let Some(path_diff_not_dot) = diff_paths(path, cwd) {
                    let path_diff_not_dot = path_diff_not_dot.to_string_lossy();
                    if path_diff_not_dot.is_empty() {
                        ".".to_string()
                    } else {
                        path_diff_not_dot.to_string()
                    }
                } else {
                    path.to_string_lossy().to_string()
                };
                Some(path_diff)
            } else {
                let new_prefix = if let Some(pfx) = diff_paths(prefix, cwd) {
                    pfx
                } else {
                    prefix.to_path_buf()
                };
                Some(new_prefix.join(remainder).to_string_lossy().to_string())
            }
        } else {
            Some(path.to_string_lossy().to_string())
        }
    } else {
        Some(path.to_string_lossy().to_string())
    };
    name.ok_or_else(|| ShellError::GenericError {
        error: format!("Invalid file name: {:}", path.to_string_lossy()),
        msg: "invalid file name".into(),
        span: Some(span),
        help: None,
        inner: vec![],
    })
}

